-- Verifica: devono risultare esattamente 300 domande HRDD, tutte attive.
do $$
declare
  v_total integer;
  v_active integer;
begin
  select count(*)::integer, count(*) filter(where active)::integer
  into v_total, v_active
  from public.question_bank
  where discipline='hrdd';

  if v_total <> 300 then
    raise exception 'Banca HRDD incompleta: attese 300 domande, trovate %', v_total;
  end if;
  if v_active <> 300 then
    raise exception 'Banca HRDD non completamente attiva: attese 300 attive, trovate %', v_active;
  end if;
end $$;

commit;

-- Controllo finale visibile nel SQL Editor.
select discipline,
       count(*)::integer as total_questions,
       count(*) filter(where active)::integer as active_questions,
       count(distinct category)::integer as categories
from public.question_bank
where discipline='hrdd'
group by discipline;
